package com.toadfx.gotrcoach.coach;

import com.toadfx.gotrcoach.plan.Strategy;
import java.util.ArrayList;
import java.util.List;

/** What happened in one round, plus its grade once the round is over. */
public class GameRecord
{
	public long endedAtMillis;
	public Strategy strategy = Strategy.TEAM;
	public boolean won;
	public boolean joinedLate;
	public int gameSeconds;
	/** Game second the first essence was crafted, -1 if never. */
	public int craftStartSecond = -1;
	/** Fragments held when the opening craft began. */
	public int fragmentsAtCraftStart;
	/** Game second of the first altar entry, -1 if never. */
	public int firstAltarSecond = -1;
	public int altarTrips;
	public int portalsSpawned;
	public int portalsEntered;
	public int idleSeconds;
	public int energyElemental;
	public int energyCatalytic;
	public int barrierRepairs;
	public boolean hitCap;
	/** Runecraft XP gained this round, including the end-of-round reward. */
	public int xpGained;

	// Filled in by the grader.
	public int score;
	public String grade = "";
	public final List<String> tips = new ArrayList<>();

	public int totalEnergy()
	{
		return energyElemental + energyCatalytic;
	}

	public double points()
	{
		return totalEnergy() / 100.0;
	}

	/** One line for saving. Tips are recalculated on load, so they are not saved. */
	public String serialize()
	{
		return endedAtMillis + "," + strategy.name() + "," + (won ? 1 : 0) + "," + gameSeconds + ","
			+ craftStartSecond + "," + fragmentsAtCraftStart + "," + firstAltarSecond + "," + altarTrips + ","
			+ portalsSpawned + "," + portalsEntered + "," + idleSeconds + "," + energyElemental + ","
			+ energyCatalytic + "," + score + "," + grade + "," + xpGained;
	}

	public static GameRecord parse(String line)
	{
		try
		{
			String[] p = line.split(",");
			if (p.length < 15)
			{
				return null;
			}
			GameRecord r = new GameRecord();
			r.endedAtMillis = Long.parseLong(p[0]);
			r.strategy = Strategy.valueOf(p[1]);
			r.won = "1".equals(p[2]);
			r.gameSeconds = Integer.parseInt(p[3]);
			r.craftStartSecond = Integer.parseInt(p[4]);
			r.fragmentsAtCraftStart = Integer.parseInt(p[5]);
			r.firstAltarSecond = Integer.parseInt(p[6]);
			r.altarTrips = Integer.parseInt(p[7]);
			r.portalsSpawned = Integer.parseInt(p[8]);
			r.portalsEntered = Integer.parseInt(p[9]);
			r.idleSeconds = Integer.parseInt(p[10]);
			r.energyElemental = Integer.parseInt(p[11]);
			r.energyCatalytic = Integer.parseInt(p[12]);
			r.score = Integer.parseInt(p[13]);
			r.grade = p[14];
			if (p.length > 15)
			{
				r.xpGained = Integer.parseInt(p[15]);
			}
			return r;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}
}

package com.toadfx.gotrcoach.coach;

import com.toadfx.gotrcoach.plan.EnergyMath;
import com.toadfx.gotrcoach.plan.Snapshot;
import com.toadfx.gotrcoach.plan.Strategy;
import com.toadfx.gotrcoach.state.GamePhase;
import com.toadfx.gotrcoach.state.Location;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

/** Watches a round tick by tick and produces a graded {@link GameRecord} at the end. */
public class GameRecorder
{
	public static final int MAX_HISTORY = 50;

	private GameRecord current;
	private GameRecord last;
	private final Deque<GameRecord> history = new ArrayDeque<>();
	private Location lastLocation = Location.OUTSIDE;
	private int lastEssence;
	private int lastFragments;
	private int idleTicks;

	/** Ticks after a round ends during which XP still counts toward it (the end-of-round reward). */
	private static final int LATE_XP_TICKS = 10;
	private int startXp = -1;
	private int lateXpTicks;

	public void start(Strategy strategy, boolean joinedLate, int runecraftXp)
	{
		startXp = runecraftXp;
		lateXpTicks = 0;
		current = new GameRecord();
		current.strategy = strategy;
		current.joinedLate = joinedLate;
		idleTicks = 0;
		lastEssence = 0;
		lastFragments = 0;
		lastLocation = Location.TEMPLE;
	}

	/**
	 * @param idle true when the player is standing still with nothing animating
	 * @param shouldBeBusy true when the planner has a real job for the player (not waiting)
	 */
	public void tick(Snapshot s, boolean idle, boolean shouldBeBusy, int portalsSpawned)
	{
		if (current == null || !(s.phase == GamePhase.MINING || s.phase == GamePhase.CRAFTING))
		{
			lastLocation = s.location;
			return;
		}
		int carried = s.essenceCarried();
		if (current.craftStartSecond < 0 && carried > lastEssence && s.location != Location.HUGE_REMAINS && s.fragments < lastFragments)
		{
			current.craftStartSecond = s.gameSeconds;
			current.fragmentsAtCraftStart = lastFragments;
		}
		if (s.location == Location.ALTAR_ROOM && lastLocation != Location.ALTAR_ROOM)
		{
			current.altarTrips++;
			if (current.firstAltarSecond < 0)
			{
				current.firstAltarSecond = s.gameSeconds;
			}
		}
		if (s.location == Location.HUGE_REMAINS && lastLocation != Location.HUGE_REMAINS && s.phase == GamePhase.CRAFTING)
		{
			current.portalsEntered++;
		}
		if (idle && shouldBeBusy && s.location != Location.ALTAR_ROOM)
		{
			idleTicks++;
		}
		current.portalsSpawned = portalsSpawned;
		current.energyElemental = s.energyElemental;
		current.energyCatalytic = s.energyCatalytic;
		if (EnergyMath.isFullyCapped(s.energyElemental, s.energyCatalytic, s.yewLantern))
		{
			current.hitCap = true;
		}
		lastEssence = carried;
		lastFragments = s.fragments;
		lastLocation = s.location;
	}

	/** Call every tick with the player's Runecraft XP. */
	public void trackXp(int runecraftXp)
	{
		if (startXp < 0 || runecraftXp <= 0)
		{
			return;
		}
		if (current != null)
		{
			current.xpGained = Math.max(0, runecraftXp - startXp);
		}
		else if (last != null && lateXpTicks > 0)
		{
			last.xpGained = Math.max(last.xpGained, runecraftXp - startXp);
			lateXpTicks--;
		}
	}

	/** XP gained so far in the round being recorded, or -1. */
	public int currentXp()
	{
		return current == null ? -1 : current.xpGained;
	}

	/** True while the end-of-round XP can still land on the last record. */
	public boolean awaitingLateXp()
	{
		return lateXpTicks > 0;
	}

	/** Ends the round. Returns the graded record, or null if no round was being recorded. */
	public GameRecord finish(boolean won, int gameSeconds, int energyElemental, int energyCatalytic, long nowMillis)
	{
		if (current == null)
		{
			return null;
		}
		GameRecord r = current;
		current = null;
		r.won = won;
		r.gameSeconds = gameSeconds;
		if (energyElemental >= 0)
		{
			r.energyElemental = Math.max(r.energyElemental, energyElemental);
		}
		if (energyCatalytic >= 0)
		{
			r.energyCatalytic = Math.max(r.energyCatalytic, energyCatalytic);
		}
		r.idleSeconds = (int) Math.round(idleTicks * 0.6);
		r.endedAtMillis = nowMillis;
		lateXpTicks = LATE_XP_TICKS;
		Grader.grade(r);
		last = r;
		if (!r.joinedLate)
		{
			history.addFirst(r);
			while (history.size() > MAX_HISTORY)
			{
				history.removeLast();
			}
		}
		return r;
	}

	public boolean isRecording()
	{
		return current != null;
	}

	public GameRecord getLast()
	{
		return last;
	}

	public List<GameRecord> getHistory()
	{
		return new ArrayList<>(history);
	}

	/** Average XP per round over the most recent n rounds that recorded XP, or -1. */
	public double averageXp(int n)
	{
		int count = 0;
		double total = 0;
		for (GameRecord r : history)
		{
			if (count >= n)
			{
				break;
			}
			if (r.xpGained > 0)
			{
				total += r.xpGained;
				count++;
			}
		}
		return count == 0 ? -1 : total / count;
	}

	/** Averages over the most recent n graded rounds: {score, points, seconds}. */
	public double[] averages(int n)
	{
		int count = 0;
		double score = 0;
		double points = 0;
		double seconds = 0;
		for (GameRecord r : history)
		{
			if (count >= n)
			{
				break;
			}
			if (r.score < 0)
			{
				continue;
			}
			score += r.score;
			points += r.points();
			seconds += r.gameSeconds;
			count++;
		}
		if (count == 0)
		{
			return null;
		}
		return new double[]{score / count, points / count, seconds / count, count};
	}

	public String serializeHistory()
	{
		StringBuilder sb = new StringBuilder();
		for (GameRecord r : history)
		{
			if (sb.length() > 0)
			{
				sb.append(';');
			}
			sb.append(r.serialize());
		}
		return sb.toString();
	}

	public void loadHistory(String saved)
	{
		history.clear();
		if (saved == null || saved.isEmpty())
		{
			return;
		}
		for (String line : saved.split(";"))
		{
			GameRecord r = GameRecord.parse(line);
			if (r != null)
			{
				history.addLast(r);
			}
		}
		last = history.peekFirst();
	}

	public void clearHistory()
	{
		history.clear();
		last = null;
	}
}

package com.toadfx.gotrcoach.coach;

import com.toadfx.gotrcoach.plan.EnergyMath;
import com.toadfx.gotrcoach.plan.Strategy;

/**
 * Grades a finished round against the OSRS Wiki timelines and gives the most useful tips.
 * Benchmarks: the team timeline starts crafting at 85s and uses the altar at the 135s rotation;
 * mass worlds mine longer (165-170 fragments); solo starts crafting at 80s. The wiki says the
 * team and mass strategies give 8+ points a round and solo gives 10+.
 */
public final class Grader
{
	private static final int ALTARS_OPEN = 120;

	private Grader()
	{
	}

	/** Game second the opening craft should start. */
	public static int craftStartTarget(Strategy s)
	{
		switch (s)
		{
			case MASS:
				return 105;
			case SOLO:
				return 80;
			default:
				return 85;
		}
	}

	/** Combined energy a good round reaches (100 energy = 1 point). */
	public static int energyTarget(Strategy s)
	{
		return s == Strategy.SOLO ? 1000 : 800;
	}

	public static void grade(GameRecord r)
	{
		r.tips.clear();
		int score = 100;

		if (r.joinedLate)
		{
			r.score = -1;
			r.grade = "-";
			r.tips.add("Joined part-way through, so this round isn't graded.");
			return;
		}

		// 1. Energy, the thing that actually becomes points.
		int target = energyTarget(r.strategy);
		int cap = EnergyMath.TOTAL_CAP;
		int energy = r.totalEnergy();
		if (r.hitCap || energy >= cap)
		{
			r.tips.add("Hit the energy cap. Nothing left on the table.");
		}
		else if (energy < target)
		{
			int short_ = target - energy;
			score -= Math.min(35, short_ / 20);
			r.tips.add(String.format("%.1f points, about %.1f short of a good %s round.",
				energy / 100.0, short_ / 100.0, r.strategy.toString().toLowerCase()));
		}
		if (energy < EnergyMath.XP_THRESHOLD)
		{
			score -= 10;
			r.tips.add("Under 300 energy: no end-of-round Runecraft XP this time.");
		}

		// 2. Opening: when crafting began.
		if (r.craftStartSecond >= 0)
		{
			int delta = r.craftStartSecond - craftStartTarget(r.strategy);
			if (delta > 10)
			{
				score -= Math.min(15, delta / 2);
				r.tips.add("Started crafting at " + r.craftStartSecond + "s, " + delta + "s late (aim for "
					+ craftStartTarget(r.strategy) + "s). Stop mining sooner.");
			}
			else if (delta < -20 && r.fragmentsAtCraftStart < 100)
			{
				score -= 5;
				r.tips.add("Stopped mining at " + r.craftStartSecond + "s with only " + r.fragmentsAtCraftStart
					+ " fragments. Mine a bit longer.");
			}
		}
		else
		{
			score -= 20;
			r.tips.add("No essence crafted this round.");
		}

		// 3. First altar: the wiki uses the altar at the 135s rotation at the latest.
		if (r.firstAltarSecond >= 0)
		{
			int late = r.firstAltarSecond - (ALTARS_OPEN + 15);
			if (late > 10)
			{
				score -= Math.min(10, late / 3);
				r.tips.add("First altar at " + r.firstAltarSecond + "s. Be at a guardian when they open at 120s.");
			}
		}

		// 4. Portals: each huge-remains portal is a free full load of essence.
		int missed = Math.max(0, r.portalsSpawned - r.portalsEntered);
		if (missed > 0)
		{
			score -= Math.min(20, missed * 7);
			r.tips.add("Missed " + missed + " of " + r.portalsSpawned + " portals. Each one is a free full load.");
		}

		// 5. Idle time.
		if (r.idleSeconds > 20)
		{
			score -= Math.min(15, (r.idleSeconds - 20) / 4);
			r.tips.add("About " + r.idleSeconds + "s standing still in the round.");
		}

		// 6. Balance between the two point types (reward searches use one of each).
		int diff = Math.abs(r.energyElemental - r.energyCatalytic);
		if (diff > 300 && energy > 400)
		{
			score -= 5;
			String low = r.energyElemental < r.energyCatalytic ? "elemental" : "catalytic";
			r.tips.add("Points were lopsided. Lean " + low + " next round, since each search costs one of each.");
		}

		if (!r.won)
		{
			r.tips.add(0, "The Great Guardian fell. Barriers and guardians matter more on this world.");
		}

		r.score = Math.max(0, Math.min(100, score));
		r.grade = letter(r.score);
		if (r.tips.isEmpty())
		{
			r.tips.add("Clean round. Right on the wiki timeline.");
		}
	}

	public static String letter(int score)
	{
		if (score >= 95)
		{
			return "S";
		}
		if (score >= 85)
		{
			return "A";
		}
		if (score >= 70)
		{
			return "B";
		}
		if (score >= 55)
		{
			return "C";
		}
		return "D";
	}
}

package com.toadfx.gotrcoach.coach;

import java.util.ArrayList;
import java.util.List;

/** Best-ever rounds, saved per character. Late joins don't count. */
public class PersonalBests
{
	public int mostEnergy;
	public int mostXp;
	/** Fastest round the Great Guardian was charged, in seconds (0 = none yet). */
	public int fastestWin;
	public int bestScore = -1;
	public String bestGrade = "";

	/** Checks a finished round and returns what it beat, e.g. "most points (9.4)". */
	public List<String> update(GameRecord r)
	{
		List<String> beaten = new ArrayList<>();
		if (r == null || r.joinedLate)
		{
			return beaten;
		}
		if (r.totalEnergy() > mostEnergy)
		{
			if (mostEnergy > 0)
			{
				beaten.add(String.format("most points (%.1f)", r.points()));
			}
			mostEnergy = r.totalEnergy();
		}
		if (r.xpGained > mostXp)
		{
			if (mostXp > 0)
			{
				beaten.add(String.format("most XP (%,d)", r.xpGained));
			}
			mostXp = r.xpGained;
		}
		if (r.won && r.gameSeconds > 60 && (fastestWin == 0 || r.gameSeconds < fastestWin))
		{
			if (fastestWin > 0)
			{
				beaten.add("fastest round (" + r.gameSeconds / 60 + ":" + String.format("%02d", r.gameSeconds % 60) + ")");
			}
			fastestWin = r.gameSeconds;
		}
		if (r.score > bestScore)
		{
			if (bestScore >= 0)
			{
				beaten.add("best grade (" + r.grade + " " + r.score + ")");
			}
			bestScore = r.score;
			bestGrade = r.grade;
		}
		return beaten;
	}

	/** Seeds bests from saved history, for players who had rounds before bests existed. */
	public void seed(List<GameRecord> history)
	{
		for (GameRecord r : history)
		{
			update(r);
		}
	}

	public boolean isEmpty()
	{
		return mostEnergy == 0 && mostXp == 0 && fastestWin == 0 && bestScore < 0;
	}

	public String serialize()
	{
		return mostEnergy + "," + mostXp + "," + fastestWin + "," + bestScore + "," + bestGrade;
	}

	public static PersonalBests parse(String s)
	{
		PersonalBests b = new PersonalBests();
		if (s == null || s.isEmpty())
		{
			return b;
		}
		try
		{
			String[] p = s.split(",", -1);
			b.mostEnergy = Integer.parseInt(p[0]);
			b.mostXp = Integer.parseInt(p[1]);
			b.fastestWin = Integer.parseInt(p[2]);
			b.bestScore = Integer.parseInt(p[3]);
			b.bestGrade = p.length > 4 ? p[4] : "";
		}
		catch (RuntimeException e)
		{
			return new PersonalBests();
		}
		return b;
	}
}

package com.toadfx.gotrcoach.coach;

/** Stats since the client started (or since the player reset them). */
public class Session
{
	private long startMillis;
	private boolean started;
	private int rounds;
	private int xp;
	private int energy;
	private int scoreTotal;
	private int graded;
	private int wins;

	public void reset()
	{
		startMillis = 0;
		started = false;
		rounds = 0;
		xp = 0;
		energy = 0;
		scoreTotal = 0;
		graded = 0;
		wins = 0;
	}

	/** Called when a round starts, so the session clock begins with the first round. */
	public void roundStarted(long nowMillis)
	{
		if (!started)
		{
			startMillis = nowMillis;
			started = true;
		}
	}

	public void add(GameRecord r)
	{
		if (r == null)
		{
			return;
		}
		rounds++;
		xp += Math.max(0, r.xpGained);
		energy += r.totalEnergy();
		if (r.won)
		{
			wins++;
		}
		if (r.score >= 0)
		{
			scoreTotal += r.score;
			graded++;
		}
	}

	public boolean isEmpty()
	{
		return rounds == 0;
	}

	public int getRounds()
	{
		return rounds;
	}

	public int getXp()
	{
		return xp;
	}

	public double getPoints()
	{
		return energy / 100.0;
	}

	public int getWins()
	{
		return wins;
	}

	public long elapsedMillis(long nowMillis)
	{
		return !started ? 0 : Math.max(0, nowMillis - startMillis);
	}

	/** Per-hour rate; 0 until at least a minute has passed. */
	private double perHour(double amount, long nowMillis)
	{
		long ms = elapsedMillis(nowMillis);
		return ms < 60_000 ? 0 : amount * 3_600_000.0 / ms;
	}

	public double xpPerHour(long nowMillis)
	{
		return perHour(xp, nowMillis);
	}

	public double pointsPerHour(long nowMillis)
	{
		return perHour(getPoints(), nowMillis);
	}

	public double roundsPerHour(long nowMillis)
	{
		return perHour(rounds, nowMillis);
	}

	public double averageScore()
	{
		return graded == 0 ? -1 : scoreTotal / (double) graded;
	}
}

