/** Everything drawn in the game world: altar outlines and timers, the target, the path, highlights. */
public class SceneOverlay extends Overlay
{
	private static final int LABEL_HEIGHT = 160;
	/** Rune icons sit just above the label. */
	private static final int ICON_HEIGHT = 250;

	private final Client client;
	private final GotrCoachPlugin plugin;
	private final GotrCoachConfig config;
	private final ModelOutlineRenderer outlines;
	private final ItemManager itemManager;

	@Inject
	public SceneOverlay(Client client, GotrCoachPlugin plugin, GotrCoachConfig config, ModelOutlineRenderer outlines,
		ItemManager itemManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.outlines = outlines;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		GameTracker tracker = plugin.getTracker();
		if (tracker == null || tracker.getPhase() == GamePhase.IDLE)
		{
			return null;
		}
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		Snapshot s = plugin.getSnapshot();
		int width = config.outlineWidth();
		int feather = config.outlineFeather();

		drawPath(g);
		drawHighlights(g, tracker, s, width, feather);
		drawAltars(g, tracker, s, width, feather);
		drawTarget(g, width, feather);
		return null;
	}

	// ------------------------------------------------------------ path

	private void drawPath(Graphics2D g)
	{
		GotrCoachConfig.PathStyle style = config.pathStyle();
		List<WorldPoint> path = plugin.getPath();
		if (style == GotrCoachConfig.PathStyle.OFF || path.size() < 2)
		{
			return;
		}
		Color color = pathColor();
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return;
		}
		boolean tiles = style == GotrCoachConfig.PathStyle.TILES || style == GotrCoachConfig.PathStyle.LINE_AND_TILES;
		boolean line = style == GotrCoachConfig.PathStyle.LINE || style == GotrCoachConfig.PathStyle.LINE_AND_TILES;
		if (tiles)
		{
			Color fill = new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.min(60, color.getAlpha()));
			List<WorldPoint> all = plugin.getPathTiles();
			for (int i = 1; i < all.size(); i++)
			{
				LocalPoint lp = LocalPoint.fromWorld(wv, all.get(i));
				if (lp == null)
				{
					continue;
				}
				Polygon poly = Perspective.getCanvasTilePoly(client, lp);
				if (poly != null)
				{
					OverlayUtil.renderPolygon(g, poly, color, fill, new BasicStroke(1));
				}
			}
		}
		if (line)
		{
			drawLine(g, wv, path, color);
		}
	}

	/** One colour for the path: red for the portal, the urgent colour when urgent, else the path colour. */
	private Color pathColor()
	{
		if (portalStep())
		{
			return config.portalColor();
		}
		if (plugin.getInstruction().getUrgency() == Urgency.NOW)
		{
			return config.urgentColor();
		}
		return arrivalColor(plugin.getTargetTicks(), plugin.getDeadlineTicks(), config.pathColor());
	}

	/**
	 * The route as straight legs (or rounded corners if turned on). It starts at the player's drawn
	 * position, drops legs already walked, goes dashed over the rubble shortcut, and disappears once
	 * you're next to the target.
	 */
	private void drawLine(Graphics2D g, WorldView wv, List<WorldPoint> path, Color color)
	{
		net.runelite.api.Player me = client.getLocalPlayer();
		LocalPoint here = me == null ? null : me.getLocalLocation();
		if (here == null)
		{
			return;
		}
		WorldPoint hereTile = WorldPoint.fromLocal(client, here);
		WorldPoint goal = path.get(path.size() - 1);
		if (hereTile != null && hereTile.getPlane() == goal.getPlane()
			&& Math.abs(hereTile.getX() - goal.getX()) <= 1 && Math.abs(hereTile.getY() - goal.getY()) <= 1)
		{
			return;
		}

		// Skip legs already walked: start after the leg the player is standing nearest to.
		int first = 1;
		double nearest = 2.0;
		double px = here.getX() / 128.0;
		double py = here.getY() / 128.0;
		for (int k = 0; k + 1 < path.size(); k++)
		{
			if (isShortcut(path.get(k), path.get(k + 1)))
			{
				continue;
			}
			LocalPoint a = LocalPoint.fromWorld(wv, path.get(k));
			LocalPoint b = LocalPoint.fromWorld(wv, path.get(k + 1));
			if (a == null || b == null)
			{
				continue;
			}
			double d = distanceToLeg(px, py, a.getX() / 128.0, a.getY() / 128.0, b.getX() / 128.0, b.getY() / 128.0);
			if (d <= nearest)
			{
				nearest = d;
				first = k + 1;
			}
		}

		Point prev = Perspective.localToCanvas(client, here, wv.getPlane());
		WorldPoint prevWorld = hereTile;
		Color stroke = new Color(color.getRed(), color.getGreen(), color.getBlue(), color.getAlpha());
		g.setColor(stroke);
		BasicStroke solid = new BasicStroke(config.pathWidth(), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
		BasicStroke dashed = new BasicStroke(config.pathWidth(), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 10f,
			new float[]{8f, 8f}, 0f);

		boolean shortcutAhead = false;
		for (int k = Math.max(0, first - 1); k + 1 < path.size(); k++)
		{
			shortcutAhead |= isShortcut(path.get(k), path.get(k + 1));
		}
		// Rounded corners can't show the dashed rubble climb, so that route draws straight.
		if (config.roundCorners() && !shortcutAhead)
		{
			java.awt.geom.Path2D.Double shape = new java.awt.geom.Path2D.Double();
			List<Point> pts = new java.util.ArrayList<>();
			if (prev != null)
			{
				pts.add(prev);
			}
			for (int i = first; i < path.size(); i++)
			{
				LocalPoint lp = LocalPoint.fromWorld(wv, path.get(i));
				Point p = lp == null ? null : Perspective.localToCanvas(client, lp, wv.getPlane());
				if (p != null)
				{
					pts.add(p);
				}
			}
			Point end = targetCentre(wv);
			if (end != null)
			{
				pts.add(end);
			}
			if (pts.size() < 2)
			{
				return;
			}
			shape.moveTo(pts.get(0).getX(), pts.get(0).getY());
			for (int i = 1; i < pts.size() - 1; i++)
			{
				Point c = pts.get(i);
				Point n = pts.get(i + 1);
				shape.quadTo(c.getX(), c.getY(), (c.getX() + n.getX()) / 2.0, (c.getY() + n.getY()) / 2.0);
			}
			shape.lineTo(pts.get(pts.size() - 1).getX(), pts.get(pts.size() - 1).getY());
			g.setStroke(solid);
			g.draw(shape);
			return;
		}

		for (int i = first; i < path.size(); i++)
		{
			WorldPoint wp = path.get(i);
			LocalPoint lp = LocalPoint.fromWorld(wv, wp);
			if (lp == null)
			{
				break;
			}
			Point p = Perspective.localToCanvas(client, lp, wv.getPlane());
			if (p != null && prev != null)
			{
				WorldPoint from = i == first ? prevWorld : path.get(i - 1);
				g.setStroke(from != null && isShortcut(from, wp) ? dashed : solid);
				g.drawLine(prev.getX(), prev.getY(), p.getX(), p.getY());
			}
			prev = p;
		}
		// Finish on the target itself, not the tile you stand on to use it.
		Point end = targetCentre(wv);
		if (end != null && prev != null)
		{
			g.setStroke(solid);
			g.drawLine(prev.getX(), prev.getY(), end.getX(), end.getY());
		}
	}

	/** Where the line should end: the centre of the target object or NPC, at ground level. */
	private Point targetCentre(WorldView wv)
	{
		LocalPoint lp = null;
		TileObject obj = plugin.getTargetObject();
		NPC npc = plugin.getTargetNpc();
		if (obj != null)
		{
			lp = obj.getLocalLocation();
		}
		else if (npc != null)
		{
			lp = npc.getLocalLocation();
		}
		return lp == null ? null : Perspective.localToCanvas(client, lp, wv.getPlane());
	}

	/** The rubble climb between the temple and the large remains. */
	private static boolean isShortcut(WorldPoint a, WorldPoint b)
	{
		WorldPoint x = GotrCoachPlugin.RUBBLE_TEMPLE_SIDE;
		WorldPoint y = GotrCoachPlugin.RUBBLE_REMAINS_SIDE;
		return (same(a, x) && same(b, y)) || (same(a, y) && same(b, x));
	}

	private static boolean same(WorldPoint a, WorldPoint b)
	{
		return a.getX() == b.getX() && a.getY() == b.getY() && a.getPlane() == b.getPlane();
	}

	private static double distanceToLeg(double px, double py, double ax, double ay, double bx, double by)
	{
		double abx = bx - ax;
		double aby = by - ay;
		double len = abx * abx + aby * aby;
		double t = len == 0 ? 0 : Math.max(0, Math.min(1, ((px - ax) * abx + (py - ay) * aby) / len));
		double dx = px - ax - t * abx;
		double dy = py - ay - t * aby;
		return Math.sqrt(dx * dx + dy * dy);
	}

	// ------------------------------------------------------------ target

	private void drawTarget(Graphics2D g, int width, int feather)
	{
		boolean urgent = plugin.getInstruction().getUrgency() == Urgency.NOW;
		Color color = urgent ? config.urgentColor() : config.targetColor();
		String label = null;
		if (config.travelLabel() && plugin.getTargetTicks() > 0)
		{
			label = plugin.getTargetTicks() + (plugin.getTargetTicks() == 1 ? " tick" : " ticks");
		}
		Color labelColor = arrivalColor(plugin.getTargetTicks(), plugin.getDeadlineTicks(), color);
		if (portalStep())
		{
			color = config.portalColor();
			labelColor = config.portalColor();
		}

		TileObject obj = plugin.getTargetObject();
		NPC npc = plugin.getTargetNpc();
		boolean altarTarget = plugin.getInstruction().getTarget() == Target.ALTAR_PORTAL;
		if (obj != null)
		{
			if (config.outlineTarget() && !altarTarget)
			{
				outlines.drawOutline(obj, width + 1, color, feather);
			}
			if (label != null && !altarTarget)
			{
				Point p = obj.getCanvasTextLocation(g, label, LABEL_HEIGHT / 2);
				if (p != null)
				{
					OverlayUtil.renderTextLocation(g, p, label, labelColor);
				}
			}
		}
		else if (npc != null)
		{
			if (config.outlineTarget())
			{
				outlines.drawOutline(npc, width + 1, color, feather);
			}
			if (label != null)
			{
				Point p = npc.getCanvasTextLocation(g, label, npc.getLogicalHeight() + 40);
				if (p != null)
				{
					OverlayUtil.renderTextLocation(g, p, label, labelColor);
				}
			}
		}
	}

	// ------------------------------------------------------------ altars

	private void drawAltars(Graphics2D g, GameTracker tracker, Snapshot s, int width, int feather)
	{
		Map<Altar, TileObject> portals = tracker.getAltarPortals();
		// Talisman guardians show for as long as you carry the talisman.
		for (Altar altar : s.talismans)
		{
			if (altar == s.activeElemental || altar == s.activeCatalytic || !s.inGame())
			{
				continue;
			}
			TileObject portal = portals.get(altar);
			if (portal == null)
			{
				continue;
			}
			boolean usable = Planner.usable(s, altar);
			Color color = !usable ? config.unusableColor()
				: altar == plugin.getBestAltar() ? config.bestAltarColor() : config.talismanColor();
			if (config.outlineAltars())
			{
				outlines.drawOutline(portal, altar == plugin.getBestAltar() ? width + 1 : width, color, feather);
			}
			drawRuneIcon(g, portal, altar, usable ? 1f : 0.5f);
			if (config.altarLabels())
			{
				String text = altar.getLabel() + " · talisman";
				Point p = portal.getCanvasTextLocation(g, text, LABEL_HEIGHT);
				if (p != null)
				{
					OverlayUtil.renderTextLocation(g, p, text, color);
				}
			}
		}
		if (s.phase != GamePhase.CRAFTING && s.phase != GamePhase.CLOSING)
		{
			return;
		}
		if (config.runeIconsAll())
		{
			for (Map.Entry<Altar, TileObject> e : portals.entrySet())
			{
				if (e.getKey() != s.activeElemental && e.getKey() != s.activeCatalytic && !s.talismans.contains(e.getKey()))
				{
					drawRuneIcon(g, e.getValue(), e.getKey(), 0.4f);
				}
			}
		}
		for (Altar altar : new Altar[]{s.activeElemental, s.activeCatalytic})
		{
			if (altar == null)
			{
				continue;
			}
			TileObject portal = portals.get(altar);
			if (portal == null)
			{
				continue;
			}
			boolean usable = Planner.usable(s, altar);
			Color color;
			if (!usable)
			{
				color = config.unusableColor();
			}
			else if (altar == plugin.getBestAltar())
			{
				color = config.bestAltarColor();
			}
			else if (config.colorByCellTier())
			{
				color = altar.getCellTier().getColor();
			}
			else
			{
				color = config.otherAltarColor();
			}
			if (config.outlineAltars())
			{
				int w = altar == plugin.getBestAltar() ? width + 1 : width;
				outlines.drawOutline(portal, w, color, feather);
			}
			if (config.runeIcons())
			{
				drawRuneIcon(g, portal, altar, usable ? 1f : 0.5f);
			}
			if (config.altarLabels())
			{
				StringBuilder text = new StringBuilder(altar.getLabel());
				if (s.altarTicksLeft >= 0)
				{
					text.append(' ').append(Planner.ticksToSeconds(s.altarTicksLeft)).append('s');
				}
				Color textColor = usable ? Color.WHITE : config.unusableColor();
				Integer travel = s.altarTravelTicks.get(altar);
				if (config.altarReach() && usable && travel != null && travel >= 0)
				{
					text.append(" · ").append(travel).append('t');
					textColor = arrivalColor(travel, s.altarTicksLeft, Color.WHITE);
				}
				if (!usable)
				{
					text.append(s.runecraftLevel < altar.getLevel() ? " (lvl " + altar.getLevel() + ")"
						: s.questLocked.contains(altar) ? " (quest)" : " (capped)");
				}
				Point p = portal.getCanvasTextLocation(g, text.toString(), LABEL_HEIGHT);
				if (p != null)
				{
					OverlayUtil.renderTextLocation(g, p, text.toString(), textColor);
				}
			}
		}
	}

	private void drawRuneIcon(Graphics2D g, TileObject portal, Altar altar, float alpha)
	{
		BufferedImage icon = itemManager.getImage(altar.getRuneItemId());
		LocalPoint lp = portal.getLocalLocation();
		if (icon == null || lp == null)
		{
			return;
		}
		Composite before = g.getComposite();
		if (alpha < 1f)
		{
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
		}
		OverlayUtil.renderImageLocation(client, g, lp, icon, ICON_HEIGHT);
		g.setComposite(before);
	}

	// ------------------------------------------------------------ highlights

	private void drawHighlights(Graphics2D g, GameTracker tracker, Snapshot s, int width, int feather)
	{
		Color color = config.highlightColor();
		boolean inGame = s.inGame();

		if (config.highlightGreatGuardian() && s.stones() > 0 && tracker.getGreatGuardian() != null
			&& plugin.getTargetNpc() != tracker.getGreatGuardian())
		{
			outlines.drawOutline(tracker.getGreatGuardian(), width, color, feather);
		}

		if (config.highlightEssencePiles() && inGame && s.chargedCell != null && s.hasChisel && s.guardians < s.guardiansMax)
		{
			for (TileObject pile : tracker.all(ObjectID.GOTR_GUARDIAN_SPAWN_EAST, ObjectID.GOTR_GUARDIAN_SPAWN_WEST))
			{
				if (pile != plugin.getTargetObject())
				{
					outlines.drawOutline(pile, width, s.chargedCell.getColor(), feather);
				}
			}
		}

		if (config.highlightCellTable() && s.unchargedCells == 0)
		{
			TileObject table = tracker.first(ObjectID.GOTR_UNCHARGED_CELLS);
			if (table != null && table != plugin.getTargetObject())
			{
				outlines.drawOutline(table, width, color, feather);
			}
		}

		if (config.highlightCellTiles() && inGame)
		{
			for (TileObject tile : tracker.getCellTiles())
			{
				int id = tile.getId();
				Color c;
				if (id == ObjectID.GOTR_CELL_TILE_BROKEN || id == ObjectID.GOTR_CELL_TILE_BROKEN_REPAIRABLE)
				{
					c = config.urgentColor();
				}
				else
				{
					CellTier tier = CellTier.fromTileObject(id);
					if (tier == null)
					{
						continue;
					}
					c = tier.getColor();
				}
				LocalPoint lp = tile.getLocalLocation();
				Polygon poly = lp == null ? null : Perspective.getCanvasTilePoly(client, lp);
				if (poly != null)
				{
					OverlayUtil.renderPolygon(g, poly, c);
				}
			}
		}

		if (config.highlightPortal() && tracker.isPortalOpen())
		{
			for (TileObject portal : tracker.all(ObjectID.GOTR_AGILITY_PORTAL_TOP))
			{
				if (portal != plugin.getTargetObject())
				{
					outlines.drawOutline(portal, width, config.portalColor(), feather);
				}
				int left = tracker.getPortalTicksLeft();
				if (left >= 0)
				{
					String text = "Portal " + Planner.ticksToSeconds(left) + "s";
					Color tc = config.portalColor();
					Point p = portal.getCanvasTextLocation(g, text, LABEL_HEIGHT);
					if (p != null)
					{
						OverlayUtil.renderTextLocation(g, p, text, tc);
					}
				}
			}
		}

		if (config.highlightDepositPool() && inGame && s.runeSlots > 0)
		{
			TileObject pool = tracker.first(ObjectID.GOTR_DEPOSITCHEST);
			if (pool != null && pool != plugin.getTargetObject())
			{
				outlines.drawOutline(pool, width, color, feather);
			}
		}
	}

	private boolean portalStep()
	{
		return plugin.getInstruction().getTarget() == Target.REMAINS_PORTAL;
	}

	/**
	 * Green when you will arrive with time to spare, yellow when it is close, red when the deadline
	 * passes first. With no deadline (or colouring off) the normal colour is used.
	 */
	Color arrivalColor(int travelTicks, int deadlineTicks, Color normal)
	{
		if (!config.pathTimeColors() || travelTicks < 0 || deadlineTicks < 0)
		{
			return normal;
		}
		int spare = deadlineTicks - travelTicks;
		if (spare < 0)
		{
			return new Color(255, 60, 60, normal.getAlpha());
		}
		if (spare < 5)
		{
			return new Color(255, 210, 0, normal.getAlpha());
		}
		return new Color(60, 230, 90, normal.getAlpha());
	}

	/** Exposed for the other altar's reach check in the panel. */
	public static boolean reachable(Snapshot s, Altar altar)
	{
		return AltarChooser.reachable(s, altar);
	}
}

package com.toadfx.gotrcoach.overlay;

import com.toadfx.gotrcoach.GotrCoachConfig;
import com.toadfx.gotrcoach.GotrCoachPlugin;
import com.toadfx.gotrcoach.plan.EnergyMath;
import com.toadfx.gotrcoach.plan.Planner;
import com.toadfx.gotrcoach.plan.PlannerSettings;
import com.toadfx.gotrcoach.plan.Snapshot;
import com.toadfx.gotrcoach.state.GamePhase;
import com.toadfx.gotrcoach.state.GameTracker;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The whole round on one bar, split into labelled sections: Mine, Craft essence, the altar
 * rotations, and portals (past, open and predicted). The section you're in shows a countdown,
 * the white line is now, and a goal bar sits underneath.
 */
public class TimelineOverlay extends Overlay
{
	private static final int MINING_SECONDS = 120;
	private static final int PORTAL_OPEN_SECONDS = 25;
	private static final int PORTAL_TOLERANCE = 5;
	private static final Color MINE = new Color(90, 160, 240);
	private static final Color CRAFT = new Color(150, 120, 230);
	private static final Color ALTARS = new Color(55, 60, 70);
	private static final Color ALTARS_ALT = new Color(68, 74, 86);
	private static final Color ELAPSED_TINT = new Color(70, 200, 110, 70);
	private static final Color PORTAL = new Color(255, 215, 0);
	private static final Color GOAL_BELOW = new Color(220, 70, 60);
	private static final Color GOAL_MET = new Color(70, 200, 110);

	private final GotrCoachPlugin plugin;
	private final GotrCoachConfig config;

	/** One labelled stretch of the bar, in game seconds. */
	private static final class Section
	{
		final int from;
		final int to;
		final Color fill;
		final String label;
		final Color text;

		Section(int from, int to, Color fill, String label, Color text)
		{
			this.from = from;
			this.to = to;
			this.fill = fill;
			this.label = label;
			this.text = text;
		}
	}

	@Inject
	public TimelineOverlay(GotrCoachPlugin plugin, GotrCoachConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
		setMovable(true);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		GameTracker tracker = plugin.getTracker();
		if (!config.showTimeline() || tracker == null || tracker.getPhase() == GamePhase.IDLE)
		{
			return null;
		}
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		Snapshot s = plugin.getSnapshot();
		int width = config.timelineWidth();
		int barH;
		Font headFont;
		Font barFont;
		switch (config.timelineSize())
		{
			case SMALL:
				barH = 12;
				headFont = FontManager.getRunescapeSmallFont();
				barFont = FontManager.getRunescapeSmallFont();
				break;
			case LARGE:
				barH = 22;
				headFont = FontManager.getRunescapeBoldFont();
				barFont = FontManager.getRunescapeFont();
				break;
			default:
				barH = 16;
				headFont = FontManager.getRunescapeFont();
				barFont = FontManager.getRunescapeSmallFont();
				break;
		}
		g.setFont(headFont);
		FontMetrics fm = g.getFontMetrics();
		int textH = fm.getHeight();
		int pad = 4;
		int alpha = (int) Math.round(config.timelineOpacity() * 2.55);
		Color bg = new Color(20, 20, 24, alpha);

		if (!s.inGame())
		{
			if (!config.timelineBetween())
			{
				return null;
			}
			int h = textH + pad * 2;
			g.setColor(bg);
			g.fillRoundRect(0, 0, width, h, 6, 6);
			String left = s.phase == GamePhase.ENDED ? "Round over" : "Next round";
			String right = s.countdownSeconds >= 0 ? clock(s.countdownSeconds) : "waiting";
			text(g, left, pad, pad + fm.getAscent(), Color.WHITE);
			text(g, right, width - pad - fm.stringWidth(right), pad + fm.getAscent(),
				s.countdownSeconds >= 0 && s.countdownSeconds <= 10 ? PORTAL : Color.WHITE);
			return new Dimension(width, h);
		}

		boolean goal = config.timelineGoal();
		int goalH = goal ? Math.max(5, barH / 2) : 0;
		int h = pad + textH + 2 + barH + (goal ? 3 + goalH : 0) + pad;
		g.setColor(bg);
		g.fillRoundRect(0, 0, width, h, 6, 6);

		int window = config.timelineWindow();
		double exact = plugin.getSmoothGameSeconds();
		int now = (int) exact;
		double start = Math.max(0, exact - window * 0.4);
		double end = start + window;
		int x0 = pad;
		int bw = width - pad * 2;
		int by = pad + textH + 2;
		PlannerSettings settings = plugin.currentSettings();
		int craftAt = Math.max(0, Math.min(MINING_SECONDS, MINING_SECONDS - settings.craftLeadSeconds()));

		// Header: what's happening now and how long it lasts, plus the game clock.
		text(g, header(s, tracker, now, craftAt), x0, pad + fm.getAscent(), Color.WHITE);
		String gameClock = clock(now);
		text(g, gameClock, width - pad - fm.stringWidth(gameClock), pad + fm.getAscent(), new Color(200, 200, 200));

		// Sections.
		List<Section> sections = new ArrayList<>();
		sections.add(new Section(0, craftAt, MINE, countdownLabel("Mine", 0, craftAt, now), Color.WHITE));
		if (craftAt < MINING_SECONDS)
		{
			sections.add(new Section(craftAt, MINING_SECONDS, CRAFT, countdownLabel("Craft", craftAt, MINING_SECONDS, now), Color.WHITE));
		}
		addAltarSections(sections, s, now, (int) end);

		g.setColor(ALTARS);
		g.fillRect(x0, by, bw, barH);
		for (Section sec : sections)
		{
			fillSpan(g, sec.from, sec.to, start, end, x0, bw, by, barH, sec.fill);
		}
		// Tint the time already gone.
		fillSpan(g, (int) start, now, start, end, x0, bw, by, barH, ELAPSED_TINT);

		// Portals on top.
		List<Section> portals = new ArrayList<>();
		if (config.timelinePortals())
		{
			for (int t : tracker.getPortalSpawnSeconds())
			{
				boolean open = s.portalOpen && t == tracker.getLastPortalGameSecond();
				int close = open && s.portalTicksLeft >= 0 ? now + Planner.ticksToSeconds(s.portalTicksLeft) : t + PORTAL_OPEN_SECONDS;
				String label = open ? "Portal " + clock(Math.max(0, close - now)) : "Portal";
				portals.add(new Section(t, close, open ? config.portalColor() : withAlpha(PORTAL, 200), label,
					open ? Color.WHITE : Color.BLACK));
			}
			int next = tracker.getNextPortalGameSecond();
			if (next >= 0 && !s.portalOpen)
			{
				for (int t = next; t < (int) end; t += GameTracker.PORTAL_INTERVAL_SECONDS)
				{
					String label = t == next ? "Portal ~" + clock(Math.max(0, t - now)) : "Portal?";
					portals.add(new Section(t - PORTAL_TOLERANCE, t + PORTAL_OPEN_SECONDS, withAlpha(PORTAL, 90), label, PORTAL));
				}
			}
			for (Section p : portals)
			{
				fillSpan(g, p.from, p.to, start, end, x0, bw, by, barH, p.fill);
			}
		}

		// Section dividers.
		g.setColor(new Color(0, 0, 0, 120));
		for (Section sec : sections)
		{
			int dx = toX(sec.to, start, end, x0, bw);
			if (sec.to > start && sec.to < end)
			{
				g.fillRect(dx, by, 1, barH);
			}
		}

		// Labels, clipped to their own section so they never spill over.
		g.setFont(barFont);
		FontMetrics bfm = g.getFontMetrics();
		for (Section sec : sections)
		{
			int[] free = freeSpan(sec, portals, start, end);
			if (free != null)
			{
				label(g, bfm, new Section(free[0], free[1], sec.fill, sec.label, sec.text), start, end, x0, bw, by, barH);
			}
		}
		for (Section p : portals)
		{
			label(g, bfm, p, start, end, x0, bw, by, barH);
		}

		// Now.
		int nx = toX(exact, start, end, x0, bw);
		g.setColor(Color.WHITE);
		g.setStroke(new BasicStroke(2));
		g.drawLine(nx, by - 3, nx, by + barH + 2);

		// Goal bar.
		if (goal)
		{
			drawGoal(g, s, settings, x0, bw, by + barH + 3, goalH, alpha, headFont);
		}
		return new Dimension(width, h);
	}

	/** Altar rotations: the current one ends when the HUD says; later ones are shown as one stretch. */
	private static void addAltarSections(List<Section> out, Snapshot s, int now, int end)
	{
		if (s.phase != GamePhase.CRAFTING && s.phase != GamePhase.CLOSING)
		{
			out.add(new Section(MINING_SECONDS, Math.max(end, MINING_SECONDS + 1), ALTARS, "Altars", Color.WHITE));
			return;
		}
		int rotateAt = s.altarTicksLeft >= 0 ? now + Planner.ticksToSeconds(s.altarTicksLeft) : -1;
		String open = altarPair(s);
		if (rotateAt < 0)
		{
			out.add(new Section(MINING_SECONDS, Math.max(end, MINING_SECONDS + 1), ALTARS, open, Color.WHITE));
			return;
		}
		out.add(new Section(MINING_SECONDS, rotateAt, ALTARS_ALT, open + " " + clock(Math.max(0, rotateAt - now)), Color.WHITE));
		if (rotateAt < end)
		{
			out.add(new Section(rotateAt, end, ALTARS, "Next altars", new Color(180, 180, 180)));
		}
	}

	private static String altarPair(Snapshot s)
	{
		String e = s.activeElemental == null ? null : s.activeElemental.getLabel();
		String c = s.activeCatalytic == null ? null : s.activeCatalytic.getLabel();
		if (e == null && c == null)
		{
			return "Altars";
		}
		if (e == null || c == null)
		{
			return e == null ? c : e;
		}
		return e + " / " + c;
	}

	private String header(Snapshot s, GameTracker tracker, int now, int craftAt)
	{
		switch (s.phase)
		{
			case MINING:
				if (now < craftAt)
				{
					return "Mining · craft in " + clock(craftAt - now);
				}
				return "Craft essence · altars in " + clock(Math.max(0, s.secondsUntilAltars));
			case CLOSING:
				return "Closing · hand in now";
			default:
				if (s.portalOpen && s.portalTicksLeft >= 0)
				{
					return "Portal open · " + clock(Planner.ticksToSeconds(s.portalTicksLeft)) + " left";
				}
				String open = altarPair(s);
				if (s.altarTicksLeft >= 0)
				{
					return open + " · rotate in " + clock(Planner.ticksToSeconds(s.altarTicksLeft));
				}
				return open;
		}
	}

	/** "Mine 0:23" while you're in that section, just "Mine" otherwise. */
	private static String countdownLabel(String name, int from, int to, int now)
	{
		if (now >= from && now < to)
		{
			return name + " " + clock(to - now);
		}
		return name;
	}

	private void drawGoal(Graphics2D g, Snapshot s, PlannerSettings settings, int x0, int bw, int gy, int goalH, int alpha, Font restore)
	{
		int have;
		int want;
		String label;
		if (s.phase == GamePhase.MINING)
		{
			have = s.fragments;
			want = settings.openingFragments();
			label = have + " / " + want + " fragments";
		}
		else
		{
			have = s.energyElemental + s.energyCatalytic;
			want = config.energyGoal() > 0 ? config.energyGoal() : EnergyMath.totalCap(s.yewLantern);
			label = String.format("%.1f / %.1f points", have / 100.0, want / 100.0);
		}
		g.setColor(new Color(60, 60, 60, alpha));
		g.fillRect(x0, gy, bw, goalH);
		double frac = want <= 0 ? 0 : Math.min(1.0, have / (double) want);
		g.setColor(have >= want ? GOAL_MET : GOAL_BELOW);
		g.fillRect(x0, gy, (int) (bw * frac), goalH);
		if (goalH >= 8)
		{
			g.setFont(FontManager.getRunescapeSmallFont());
			FontMetrics sm = g.getFontMetrics();
			text(g, label, x0 + (bw - sm.stringWidth(label)) / 2, gy + goalH - 1, Color.WHITE);
			g.setFont(restore);
		}
	}

	private static void label(Graphics2D g, FontMetrics fm, Section sec, double start, double end, int x0, int bw, int by, int barH)
	{
		double a = Math.max(sec.from, start);
		double b = Math.min(sec.to, end);
		if (b <= a || sec.label == null || sec.label.isEmpty())
		{
			return;
		}
		int xa = toX(a, start, end, x0, bw);
		int xb = toX(b, start, end, x0, bw);
		int room = xb - xa - 4;
		String text = sec.label;
		if (fm.stringWidth(text) > room)
		{
			// Too narrow: try the countdown alone (e.g. "0:23"), else skip the label.
			int space = text.lastIndexOf(' ');
			text = space > 0 ? text.substring(space + 1) : text;
			if (fm.stringWidth(text) > room)
			{
				return;
			}
		}
		int tx = xa + (xb - xa - fm.stringWidth(text)) / 2;
		int ty = by + (barH + fm.getAscent() - fm.getDescent()) / 2;
		Shape clip = g.getClip();
		g.clipRect(xa, by, xb - xa, barH);
		if (sec.text == Color.BLACK)
		{
			g.setColor(Color.BLACK);
			g.drawString(text, tx, ty);
		}
		else
		{
			text(g, text, tx, ty, sec.text);
		}
		g.setClip(clip);
	}

	/** The widest part of a section not covered by a portal, so labels never sit on top of each other. */
	private static int[] freeSpan(Section sec, List<Section> covers, double start, double end)
	{
		List<int[]> free = new ArrayList<>();
		free.add(new int[]{Math.max(sec.from, (int) Math.ceil(start)), Math.min(sec.to, (int) end)});
		for (Section c : covers)
		{
			List<int[]> next = new ArrayList<>();
			for (int[] f : free)
			{
				if (c.to <= f[0] || c.from >= f[1])
				{
					next.add(f);
					continue;
				}
				if (c.from > f[0])
				{
					next.add(new int[]{f[0], c.from});
				}
				if (c.to < f[1])
				{
					next.add(new int[]{c.to, f[1]});
				}
			}
			free = next;
		}
		int[] best = null;
		for (int[] f : free)
		{
			if (f[1] > f[0] && (best == null || f[1] - f[0] > best[1] - best[0]))
			{
				best = f;
			}
		}
		return best;
	}

	private static int toX(double t, double start, double end, int x0, int bw)
	{
		return x0 + (int) Math.round((t - start) * bw / (end - start));
	}

	private static void fillSpan(Graphics2D g, int from, int to, double start, double end, int x0, int bw, int y, int h, Color c)
	{
		double a = Math.max(from, start);
		double b = Math.min(to, end);
		if (b <= a)
		{
			return;
		}
		int xa = toX(a, start, end, x0, bw);
		int xb = toX(b, start, end, x0, bw);
		g.setColor(c);
		g.fillRect(xa, y, Math.max(1, xb - xa), h);
	}

	static String clock(int seconds)
	{
		return GotrCoachPlugin.formatTime(Math.max(0, seconds));
	}

	private static Color withAlpha(Color c, int a)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), a);
	}

	private static void text(Graphics2D g, String s, int x, int y, Color c)
	{
		g.setColor(Color.BLACK);
		g.drawString(s, x + 1, y + 1);
		g.setColor(c);
		g.drawString(s, x, y);
	}
}

package com.toadfx.gotrcoach.plan;

import com.toadfx.gotrcoach.model.Alignment;
import com.toadfx.gotrcoach.model.Altar;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * Picks which altar to use: the two open altars, plus any altar you hold a portal talisman for
 * (a talisman opens its guardian even when it is inactive). Pure logic so it can be tested.
 */
public final class AltarChooser
{
	/** Result of a choice: the altar to use, the backup, and a short reason for the panel. */
	public static final class Choice
	{
		public final Altar primary;
		public final Altar secondary;
		public final String reason;
		/** True when the primary altar is reached with a portal talisman rather than because it's open. */
		public final boolean viaTalisman;

		Choice(Altar primary, Altar secondary, String reason, boolean viaTalisman)
		{
			this.primary = primary;
			this.secondary = secondary;
			this.reason = reason;
			this.viaTalisman = viaTalisman;
		}
	}

	private AltarChooser()
	{
	}

	/** True when the player can reach the altar before it rotates (or when we cannot tell). */
	public static boolean reachable(Snapshot s, Altar altar)
	{
		if (isTalismanOnly(s, altar))
		{
			return true;
		}
		Integer travel = s.altarTravelTicks.get(altar);
		if (travel == null || travel < 0 || s.altarTicksLeft < 0)
		{
			return true;
		}
		return travel <= s.altarTicksLeft;
	}

	/** Reached only through a talisman (it isn't one of the open altars). */
	public static boolean isTalismanOnly(Snapshot s, Altar altar)
	{
		return altar != s.activeElemental && altar != s.activeCatalytic && s.talismans.contains(altar);
	}

	/** Every altar the player could use right now: open ones plus talisman ones. */
	public static List<Altar> usable(Snapshot s)
	{
		List<Altar> out = new ArrayList<>(4);
		List<Altar> candidates = new ArrayList<>(4);
		candidates.add(s.activeElemental);
		candidates.add(s.activeCatalytic);
		candidates.addAll(s.talismans);
		for (Altar a : candidates)
		{
			if (a == null || out.contains(a) || !s.canEnter(a))
			{
				continue;
			}
			if (EnergyMath.isCapped(a.getAlignment(), s.energyElemental, s.energyCatalytic, s.yewLantern))
			{
				continue;
			}
			out.add(a);
		}
		return out;
	}

	public static Choice choose(Snapshot s, PlannerSettings settings)
	{
		List<Altar> usable = usable(s);
		if (usable.isEmpty())
		{
			return null;
		}
		List<Altar> pool = new ArrayList<>(usable.size());
		for (Altar a : usable)
		{
			if (reachable(s, a))
			{
				pool.add(a);
			}
		}
		boolean noneReachable = pool.isEmpty();
		if (noneReachable)
		{
			// Nothing reachable before rotation: still name the best usable one so the player can wait by it.
			pool = usable;
		}

		long pointsE = s.energyElemental;
		long pointsC = s.energyCatalytic;
		if (settings.balanceWithBanked && s.bankedElemental >= 0 && s.bankedCatalytic >= 0)
		{
			pointsE += s.bankedElemental * 100L;
			pointsC += s.bankedCatalytic * 100L;
		}
		Alignment lower = pointsE <= pointsC ? Alignment.ELEMENTAL : Alignment.CATALYTIC;
		AltarMode mode = settings.altarMode;

		List<Altar> ranked = new ArrayList<>(pool);
		ranked.sort(Comparator.comparingDouble((Altar a) -> score(a, mode, lower)).reversed());
		Altar pick = ranked.get(0);
		String why = reason(pick, mode, lower, pool.size());

		// Balance override: too far apart, so take the best altar of the weaker type if there is one.
		long diff = Math.abs(pointsE - pointsC);
		boolean onlyMode = mode == AltarMode.ELEMENTAL_ONLY || mode == AltarMode.CATALYTIC_ONLY;
		if (!onlyMode && pick.getAlignment() != lower && settings.maxImbalance > 0 && diff > settings.maxImbalance)
		{
			for (Altar a : ranked)
			{
				if (a.getAlignment() == lower)
				{
					pick = a;
					why = "rebalancing, fewer " + lower.getLabel().toLowerCase() + " points";
					break;
				}
			}
		}

		Altar secondary = null;
		for (Altar a : ranked)
		{
			if (a != pick)
			{
				secondary = a;
				break;
			}
		}
		if (secondary == null && usable.size() > 1)
		{
			for (Altar a : usable)
			{
				if (a != pick)
				{
					secondary = a;
					why = "the other altar rotates before you can reach it";
					break;
				}
			}
		}
		if (pool.size() == 1 && usable.size() == 1 && !noneReachable)
		{
			why = "only usable altar";
		}

		boolean viaTalisman = isTalismanOnly(s, pick);
		if (viaTalisman)
		{
			why = why + ", use your " + pick.getLabel().toLowerCase() + " talisman";
		}
		return new Choice(pick, secondary, why, viaTalisman);
	}

	/** Higher is better. Ties go to the weaker point type, then more XP. */
	static double score(Altar a, AltarMode mode, Alignment lower)
	{
		double weaker = a.getAlignment() == lower ? 1 : 0;
		double xp = a.getXpPerEssence() / 100.0;
		switch (mode)
		{
			case ELEMENTAL_ONLY:
				return (a.getAlignment() == Alignment.ELEMENTAL ? 100 : 0) + weaker + xp;
			case CATALYTIC_ONLY:
				return (a.getAlignment() == Alignment.CATALYTIC ? 100 : 0) + weaker + xp;
			case BALANCED:
				return weaker * 10 + xp;
			case BEST_CELL:
				return a.getCellTier().getRank() * 10 + weaker + xp;
			case EXPERIENCE:
				return a.getXpPerEssence() * 10 + weaker;
			case EVEN_POINTS:
			default:
				// Wiki: Blood and Death first, then Fire and Earth, then the type you have fewer points in.
				double tier = (a == Altar.BLOOD || a == Altar.DEATH) ? 3 : (a == Altar.FIRE || a == Altar.EARTH) ? 2 : 0;
				return tier * 10 + weaker + xp;
		}
	}

	private static String reason(Altar pick, AltarMode mode, Alignment lower, int options)
	{
		String fewer = "fewer " + lower.getLabel().toLowerCase() + " points";
		switch (mode)
		{
			case ELEMENTAL_ONLY:
				return "elemental only";
			case CATALYTIC_ONLY:
				return "catalytic only";
			case BALANCED:
				return fewer;
			case BEST_CELL:
				return pick.getCellTier().getLabel().toLowerCase() + " cell";
			case EXPERIENCE:
				return "more XP per essence";
			case EVEN_POINTS:
			default:
				if (pick == Altar.BLOOD || pick == Altar.DEATH || pick == Altar.FIRE || pick == Altar.EARTH)
				{
					return pick.getLabel() + " first (wiki)";
				}
				return options > 1 ? fewer : "only usable altar";
		}
	}
}

package com.toadfx.gotrcoach.plan;

/** How the altar chooser ranks the two open altars. */
public enum AltarMode
{
	/** Wiki even-points rule: Blood/Death, then Fire/Earth, then whichever type you have fewer points in. */
	EVEN_POINTS("Even points (wiki)"),
	/** Always the type you have fewer points in. */
	BALANCED("Strict balance"),
	/** The altar that gives the best cell. */
	BEST_CELL("Best cell"),
	/** The altar that gives the most Runecraft XP per essence. */
	EXPERIENCE("Most XP"),
	/** Elemental only (e.g. for combination runes). */
	ELEMENTAL_ONLY("Elemental only"),
	/** Catalytic only. */
	CATALYTIC_ONLY("Catalytic only");

	private final String label;

	AltarMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.toadfx.gotrcoach.plan;

import com.toadfx.gotrcoach.model.Alignment;

/**
 * Energy and point rules from the OSRS Wiki:
 * 1 point per 100 energy (the remainder is a % chance of one more),
 * at most 1,000 energy of each type and 1,200 in total per game (1,320 with yew logs in the lantern),
 * and at least 300 total energy for the end-of-game XP.
 */
public final class EnergyMath
{
	public static final int TYPE_CAP = 1000;
	public static final int TOTAL_CAP = 1200;
	public static final int TOTAL_CAP_YEW = 1320;
	public static final int XP_THRESHOLD = 300;
	public static final int ENERGY_PER_STONE = 2;
	public static final int ENERGY_PER_POLY_STONE = 3;

	private EnergyMath()
	{
	}

	public static int totalCap(boolean yewLantern)
	{
		return yewLantern ? TOTAL_CAP_YEW : TOTAL_CAP;
	}

	/** How much more energy of this type can still count this game. */
	public static int room(Alignment type, int elemental, int catalytic, boolean yewLantern)
	{
		int mine = type == Alignment.ELEMENTAL ? elemental : catalytic;
		int byType = TYPE_CAP - mine;
		int byTotal = totalCap(yewLantern) - (elemental + catalytic);
		return Math.max(0, Math.min(byType, byTotal));
	}

	public static boolean isCapped(Alignment type, int elemental, int catalytic, boolean yewLantern)
	{
		return room(type, elemental, catalytic, yewLantern) <= 0;
	}

	public static boolean isFullyCapped(int elemental, int catalytic, boolean yewLantern)
	{
		return isCapped(Alignment.ELEMENTAL, elemental, catalytic, yewLantern)
			&& isCapped(Alignment.CATALYTIC, elemental, catalytic, yewLantern);
	}

	/** Expected points from an amount of energy (whole points plus the chance of one more). */
	public static double expectedPoints(int energy)
	{
		return Math.max(0, energy) / 100.0;
	}

	/** Energy each type would have once the given stones are handed in, respecting the caps. */
	public static int[] afterHandIn(int elemental, int catalytic, int elementalStones, int catalyticStones, int polyStones, boolean yewLantern)
	{
		int e = elemental;
		int c = catalytic;
		// Treat poly stones as part of whichever type they were counted in; give them the extra energy first.
		int polyE = Math.min(polyStones, elementalStones);
		int polyC = Math.min(polyStones - polyE, catalyticStones);
		int addE = polyE * ENERGY_PER_POLY_STONE + (elementalStones - polyE) * ENERGY_PER_STONE;
		int addC = polyC * ENERGY_PER_POLY_STONE + (catalyticStones - polyC) * ENERGY_PER_STONE;
		int roomE = room(Alignment.ELEMENTAL, e, c, yewLantern);
		e += Math.min(addE, roomE);
		int roomC = room(Alignment.CATALYTIC, e, c, yewLantern);
		c += Math.min(addC, roomC);
		return new int[]{e, c};
	}

	/** Energy the stones would waste because a cap is already reached. */
	public static int wasted(int elemental, int catalytic, int elementalStones, int catalyticStones, int polyStones, boolean yewLantern)
	{
		int[] after = afterHandIn(elemental, catalytic, elementalStones, catalyticStones, polyStones, yewLantern);
		int polyE = Math.min(polyStones, elementalStones);
		int polyC = Math.min(polyStones - polyE, catalyticStones);
		int add = polyE * ENERGY_PER_POLY_STONE + (elementalStones - polyE) * ENERGY_PER_STONE
			+ polyC * ENERGY_PER_POLY_STONE + (catalyticStones - polyC) * ENERGY_PER_STONE;
		return add - ((after[0] - elemental) + (after[1] - catalytic));
	}
}

package com.toadfx.gotrcoach.plan;

import com.toadfx.gotrcoach.model.Altar;
import java.util.Objects;

/** One planner result: what to do, where, and why. */
public final class Instruction
{
	public static final Instruction NONE = new Instruction(Step.OUTSIDE, Target.NONE, null, "", Urgency.NORMAL);

	private final Step step;
	private final Target target;
	private final Altar altar;
	private final String detail;
	private final Urgency urgency;
	private Altar secondaryAltar;

	public Instruction(Step step, Target target, Altar altar, String detail, Urgency urgency)
	{
		this.step = step;
		this.target = target;
		this.altar = altar;
		this.detail = detail == null ? "" : detail;
		this.urgency = urgency;
	}

	public static Instruction of(Step step, Target target, String detail)
	{
		return new Instruction(step, target, null, detail, Urgency.NORMAL);
	}

	public Step getStep()
	{
		return step;
	}

	public Target getTarget()
	{
		return target;
	}

	public Altar getAltar()
	{
		return altar;
	}

	public String getDetail()
	{
		return detail;
	}

	public Urgency getUrgency()
	{
		return urgency;
	}

	public Altar getSecondaryAltar()
	{
		return secondaryAltar;
	}

	public Instruction withSecondary(Altar secondary)
	{
		this.secondaryAltar = secondary;
		return this;
	}

	public Instruction withUrgency(Urgency u)
	{
		Instruction i = new Instruction(step, target, altar, detail, u);
		i.secondaryAltar = secondaryAltar;
		return i;
	}

	/** Title shown in the panel, e.g. "Enter the altar: Fire". */
	public String title()
	{
		if (altar != null && (step == Step.ENTER_ALTAR))
		{
			return "Enter " + altar.getLabel() + " altar";
		}
		return step.getLabel();
	}

	/** Two instructions are the same step if the player would do the same thing. */
	public boolean sameAs(Instruction other)
	{
		return other != null && step == other.step && target == other.target && altar == other.altar;
	}

	@Override
	public String toString()
	{
		return title() + (detail.isEmpty() ? "" : " - " + detail);
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof Instruction))
		{
			return false;
		}
		Instruction i = (Instruction) o;
		return sameAs(i) && detail.equals(i.detail) && urgency == i.urgency;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(step, target, altar, detail, urgency);
	}
}

package com.toadfx.gotrcoach.plan;

import com.toadfx.gotrcoach.model.Alignment;
import com.toadfx.gotrcoach.model.Altar;
import com.toadfx.gotrcoach.model.CellTier;
import com.toadfx.gotrcoach.state.GamePhase;
import com.toadfx.gotrcoach.state.Location;

/**
 * Turns a {@link Snapshot} into the single next thing to do, following the OSRS Wiki
 * Guardians of the Rift strategies. Pure logic: no RuneLite calls, so it is unit tested.
 */
public final class Planner
{
	/** Fragments a broken cell tile costs to repair. */
	public static final int REPAIR_COST = 12;
	/** Wiki grace-portal trick: an extra portal spawns if the grace period starts 95s+ after the last one. */
	public static final int GRACE_PORTAL_SECONDS = 95;
	/** Huge-remains portals stay open about 25 seconds; under this many ticks left it is urgent. */
	private static final int PORTAL_URGENT_TICKS = 15;

	private Planner()
	{
	}

	public static Instruction plan(Snapshot s, PlannerSettings st)
	{
		switch (s.phase)
		{
			case MINING:
				return mining(s, st);
			case CRAFTING:
				return crafting(s, st);
			case CLOSING:
				return closing(s, st);
			case WAITING:
			case ENDED:
				return between(s, st);
			case IDLE:
			default:
				return Instruction.of(Step.OUTSIDE, Target.NONE,
					"Minigame teleport, or the portal in the Wizards' Tower basement");
		}
	}

	// ---------------------------------------------------------------- between rounds

	private static Instruction between(Snapshot s, PlannerSettings st)
	{
		if (s.phase == GamePhase.ENDED && s.countdownSeconds < 0)
		{
			return Instruction.of(Step.GAME_OVER, Target.NONE, "Points are banked. Safe to leave.");
		}
		String countdown = s.countdownSeconds >= 0 ? "Starts in " + s.countdownSeconds + "s. " : "";
		if (s.pouchNeedsRepair)
		{
			return Instruction.of(Step.REPAIR_POUCHES, Target.CORDELIA,
				countdown + "NPC Contact the Dark Mage, or talk to Apprentice Cordelia");
		}
		if (!s.hasPickaxe)
		{
			return new Instruction(Step.GET_PICKAXE, Target.NONE, null,
				countdown + "You can't mine fragments without one (inventory or worn)", Urgency.SOON);
		}
		if (!s.hasChisel)
		{
			return new Instruction(Step.GET_CHISEL, Target.NONE, null,
				countdown + "Needed to craft essence and build guardians", Urgency.SOON);
		}
		if (s.location == Location.LOBBY)
		{
			return Instruction.of(Step.ENTER_BARRIER, Target.ENTRANCE_BARRIER, countdown + "Get inside before the rift opens");
		}
		if (s.unchargedCells < st.unchargedCellsWanted)
		{
			return Instruction.of(Step.TAKE_UNCHARGED_CELLS, Target.UNCHARGED_CELLS,
				countdown + s.unchargedCells + " / " + st.unchargedCellsWanted + " uncharged cells");
		}
		if (s.chargedCell == null)
		{
			return Instruction.of(Step.TAKE_WEAK_CELL, Target.WEAK_CELLS, countdown + "For your opening barrier or guardian");
		}
		if (st.strategy == Strategy.SOLO)
		{
			return Instruction.of(Step.WAIT_FOR_START, Target.ESSENCE_PILE_ELEMENTAL,
				countdown + "Build a weak elemental guardian, then one barrier between the fire and blood portals");
		}
		return Instruction.of(Step.WAIT_FOR_START, Target.CELL_TILE,
			countdown + "Stand on the barrier side of an empty tile; place your cell when the rift opens");
	}

	// ---------------------------------------------------------------- mining phase

	private static Instruction mining(Snapshot s, PlannerSettings st)
	{
		if (s.location == Location.ALTAR_ROOM)
		{
			return Instruction.of(Step.LEAVE_ALTAR, Target.ALTAR_EXIT, "");
		}
		if (s.chargedCell != null && s.gameSeconds < 30)
		{
			return placeCell(s, st);
		}
		if (s.location == Location.HUGE_REMAINS)
		{
			// Wiki: with an inter-round portal, fill up with essence first, then mine fragments.
			if (s.essenceRoom() > 0)
			{
				return Instruction.of(Step.MINE_HUGE_REMAINS, Target.HUGE_REMAINS, "Fill inventory and pouches");
			}
			return Instruction.of(Step.LEAVE_REMAINS, Target.REMAINS_PORTAL_EXIT, "Full, go mine fragments");
		}

		int target = st.openingFragments();
		int lead = st.craftLeadSeconds();
		boolean timeUp = s.secondsUntilAltars >= 0 && s.secondsUntilAltars <= lead;
		boolean craftNow = s.openingCraftStarted || s.fragments >= target || timeUp;
		Target remains = s.agilityLevel >= 56 ? Target.LARGE_REMAINS : Target.GUARDIAN_REMAINS;

		if (!craftNow)
		{
			String until = s.secondsUntilAltars >= 0
				? " · craft in " + Math.max(0, s.secondsUntilAltars - lead) + "s" : "";
			return Instruction.of(Step.MINE_FRAGMENTS, remains, s.fragments + " / " + target + " fragments" + until);
		}

		int goal = essenceGoal(s, st);
		if (s.fragments > 0 && s.essenceCarried() < goal)
		{
			return Instruction.of(Step.CRAFT_ESSENCE, Target.WORKBENCH,
				s.essenceCarried() + " / " + goal + " essence" + (s.hasPouches ? ", fill pouches as you go" : ""));
		}
		if (s.essenceCarried() < st.minEssenceForAltar && s.fragments == 0 && s.secondsUntilAltars > 20)
		{
			return Instruction.of(Step.MINE_FRAGMENTS, remains, "Not enough essence yet");
		}
		String opens = s.secondsUntilAltars >= 0 ? "Altars open in " + s.secondsUntilAltars + "s" : "Altars open soon";
		return new Instruction(Step.ENTER_ALTAR, Target.NONE, null, opens + ", wait near the middle", Urgency.NORMAL);
	}

	/** Essence to carry for the next trip. On mass worlds the first trip is a quick 30 essence. */
	static int essenceGoal(Snapshot s, PlannerSettings st)
	{
		int capacity = s.essenceCarried() + s.essenceRoom();
		if (st.strategy == Strategy.MASS && s.altarTrips == 0)
		{
			return Math.min(st.massFirstTripEssence, capacity);
		}
		return capacity;
	}

	// ---------------------------------------------------------------- crafting phase

	private static Instruction crafting(Snapshot s, PlannerSettings st)
	{
		if (s.location == Location.ALTAR_ROOM)
		{
			return inAltar(s, Urgency.NORMAL);
		}
		if (s.location == Location.HUGE_REMAINS)
		{
			if (s.essenceRoom() > 0)
			{
				return Instruction.of(Step.MINE_HUGE_REMAINS, Target.HUGE_REMAINS,
					s.essenceRoom() + " essence of room left");
			}
			return Instruction.of(Step.LEAVE_REMAINS, Target.REMAINS_PORTAL_EXIT, "Full, head to an altar");
		}

		boolean capped = EnergyMath.isFullyCapped(s.energyElemental, s.energyCatalytic, s.yewLantern);

		// Portal first: a huge-remains portal is a free full load, so it beats everything that can wait.
		if (st.portalAlways && s.portalOpen && s.essenceRoom() > 0 && portalReachable(s))
		{
			return portalStep(s, Urgency.NOW);
		}

		if (s.stones() > 0)
		{
			if (!capped && st.graceHold && s.powerPercent >= 90 && !s.portalOpen
				&& s.secondsSincePortal >= 0 && s.secondsSincePortal < GRACE_PORTAL_SECONDS)
			{
				int wait = GRACE_PORTAL_SECONDS - s.secondsSincePortal;
				return Instruction.of(Step.HOLD_STONES, Target.GREAT_GUARDIAN,
					"Hand in after " + wait + "s so the grace period gets an extra portal");
			}
			int wasted = EnergyMath.wasted(s.energyElemental, s.energyCatalytic,
				s.elementalStones, s.catalyticStones, s.polyStones, s.yewLantern);
			String detail = wasted > 0
				? wasted + " energy is over the cap (still powers the guardian)"
				: s.stones() + " stones";
			return Instruction.of(Step.POWER_UP, Target.GREAT_GUARDIAN, detail);
		}

		if (s.chargedCell != null)
		{
			return placeCell(s, st);
		}

		if (s.repairableTile && s.fragments >= REPAIR_COST)
		{
			return new Instruction(Step.REPAIR_BARRIER, Target.CELL_TILE, null,
				"Costs " + REPAIR_COST + " fragments, the guardian drains fast without it",
				s.powerPercent >= 60 ? Urgency.NOW : Urgency.SOON);
		}

		if (capped)
		{
			return Instruction.of(Step.ENERGY_CAPPED, Target.NONE,
				"Both caps reached, more runes are wasted. Heal barriers or build guardians to help finish");
		}

		if (!st.portalAlways && s.portalOpen && s.essenceRoom() >= st.portalMinRoom && portalReachable(s))
		{
			Urgency u = s.portalTicksLeft >= 0 && s.portalTicksLeft < PORTAL_URGENT_TICKS ? Urgency.NOW : Urgency.SOON;
			return portalStep(s, u);
		}

		if (st.depositRunes && s.runeSlots > 0 && s.freeSlots < st.depositBelowFreeSlots && s.fragments > 0)
		{
			return Instruction.of(Step.DEPOSIT_RUNES, Target.DEPOSIT_POOL, "Free up space before crafting essence");
		}

		if (s.fragments > 0 && s.essenceRoom() > 0)
		{
			int goal = essenceGoal(s, st);
			// Topping up a nearly full load isn't worth the walk (e.g. 2 slots after the portal),
			// and never worth losing the altar to a rotation.
			boolean worthIt = s.essenceCarried() == 0 || goal - s.essenceCarried() >= st.topUpMin;
			if (s.essenceCarried() < goal && worthIt && !rotationRush(s, st))
			{
				return Instruction.of(Step.CRAFT_ESSENCE, Target.WORKBENCH,
					s.essenceCarried() + " / " + goal + " essence");
			}
		}

		if (s.essenceCarried() > 0)
		{
			if (portalDueSoon(s, st))
			{
				return new Instruction(Step.WAIT_FOR_PORTAL, Target.NONE, null,
					"Portal in ~" + s.secondsToPortal + "s. An altar trip now means missing it", Urgency.SOON);
			}
			return enterAltar(s, st);
		}

		Target remains = s.agilityLevel >= 56 ? Target.LARGE_REMAINS : Target.GUARDIAN_REMAINS;
		return Instruction.of(Step.MINE_FRAGMENTS, remains, nextPortalHint(s));
	}

	private static Instruction portalStep(Snapshot s, Urgency urgency)
	{
		String left = s.portalTicksLeft >= 0 ? "Closes in " + ticksToSeconds(s.portalTicksLeft) + "s" : "Open now";
		String room = s.essenceRoom() + " essence of room";
		return new Instruction(Step.ENTER_REMAINS_PORTAL, Target.REMAINS_PORTAL, null, left + ", " + room, urgency);
	}

	private static Instruction inAltar(Snapshot s, Urgency urgency)
	{
		if (s.essence > 0)
		{
			return new Instruction(Step.CRAFT_RUNES, Target.ALTAR, s.altarRoom, s.essence + " essence", urgency);
		}
		if (s.essenceInPouches > 0)
		{
			return new Instruction(Step.EMPTY_POUCHES, Target.ALTAR, s.altarRoom, s.essenceInPouches + " in pouches", urgency);
		}
		return new Instruction(Step.LEAVE_ALTAR, Target.ALTAR_EXIT, s.altarRoom, "", urgency);
	}

	private static Instruction enterAltar(Snapshot s, PlannerSettings st)
	{
		AltarChooser.Choice choice = AltarChooser.choose(s, st);
		if (choice == null)
		{
			String rotate = s.altarTicksLeft >= 0 ? ", they rotate in " + ticksToSeconds(s.altarTicksLeft) + "s" : "";
			return new Instruction(Step.ENTER_ALTAR, Target.NONE, null, "No usable altar open" + rotate, Urgency.NORMAL);
		}
		Urgency u = Urgency.NORMAL;
		Integer travel = s.altarTravelTicks.get(choice.primary);
		if (travel != null && travel >= 0 && s.altarTicksLeft >= 0 && s.altarTicksLeft - travel < 5)
		{
			u = Urgency.SOON;
		}
		return new Instruction(Step.ENTER_ALTAR, Target.ALTAR_PORTAL, choice.primary, choice.reason, u)
			.withSecondary(choice.secondary);
	}

	private static Instruction placeCell(Snapshot s, PlannerSettings st)
	{
		CellTier cell = s.chargedCell;
		int wanted = st.strategy == Strategy.SOLO ? 2 : st.guardiansWanted;
		boolean opening = s.gameSeconds < 30;
		boolean slotFree = s.guardians < Math.min(wanted, s.guardiansMax);
		// Wiki: after the first phase, keep weak cells for barriers; guardians take strong/overcharged.
		boolean worthy = cell.isGuardianWorthy() || (opening && st.strategy != Strategy.SOLO);
		if (st.strategy == Strategy.SOLO && opening && cell == CellTier.WEAK && s.guardians == 0)
		{
			worthy = true;
		}
		if (s.hasChisel && slotFree && worthy)
		{
			Alignment side = s.energyElemental <= s.energyCatalytic ? Alignment.ELEMENTAL : Alignment.CATALYTIC;
			Target pile = side == Alignment.ELEMENTAL ? Target.ESSENCE_PILE_ELEMENTAL : Target.ESSENCE_PILE_CATALYTIC;
			return Instruction.of(Step.BUILD_GUARDIAN, pile,
				cell.getLabel() + " cell, " + s.guardians + "/" + wanted + " guardians up, "
					+ side.getLabel().toLowerCase() + " side");
		}
		String where;
		if (st.strategy == Strategy.SOLO)
		{
			where = "Right-most barrier, between the fire and blood portals";
		}
		else if (s.emptyTile && opening)
		{
			where = "Empty tile, build a barrier";
		}
		else
		{
			where = "Weakest barrier (healing stacks, guardians don't)";
		}
		return Instruction.of(Step.PLACE_CELL, Target.CELL_TILE, cell.getLabel() + " cell: " + where);
	}

	// ---------------------------------------------------------------- closing

	private static Instruction closing(Snapshot s, PlannerSettings st)
	{
		if (s.location == Location.ALTAR_ROOM)
		{
			return inAltar(s, Urgency.NOW);
		}
		if (s.stones() > 0)
		{
			return new Instruction(Step.HAND_IN_NOW, Target.GREAT_GUARDIAN, null,
				"The rifts close in about 30s", Urgency.NOW);
		}
		if (s.essenceCarried() > 0)
		{
			// Some altars stay open after the guardian is charged: use one, then hand in.
			AltarChooser.Choice choice = AltarChooser.choose(s, st);
			if (choice != null)
			{
				return new Instruction(Step.ENTER_ALTAR, Target.ALTAR_PORTAL, choice.primary,
					"Still open, craft and hand in before the rifts close", Urgency.NOW).withSecondary(choice.secondary);
			}
		}
		return Instruction.of(Step.GAME_OVER, Target.NONE, "Stay until the round ends so your points count");
	}

	// ---------------------------------------------------------------- helpers

	/** Running ticks a chisel run of this many essence roughly takes (about one essence per two ticks). */
	static final int TICKS_PER_ESSENCE = 2;

	/**
	 * True when you already carry a worthwhile load and stopping to chisel more would mean the best
	 * altar rotates before you get there, while going now still makes it.
	 */
	static boolean rotationRush(Snapshot s, PlannerSettings st)
	{
		if (s.essenceCarried() < st.minEssenceForAltar || s.altarTicksLeft < 0)
		{
			return false;
		}
		AltarChooser.Choice choice = AltarChooser.choose(s, st);
		if (choice == null || choice.viaTalisman)
		{
			return false;
		}
		Integer travel = s.altarTravelTicks.get(choice.primary);
		if (travel == null || travel < 0 || travel > s.altarTicksLeft)
		{
			return false;
		}
		int craftTicks = Math.min(60, (essenceGoal(s, st) - s.essenceCarried()) * TICKS_PER_ESSENCE);
		return travel + craftTicks > s.altarTicksLeft;
	}

	/** A portal is expected shortly and there's room to make it worth waiting for. */
	static boolean portalDueSoon(Snapshot s, PlannerSettings st)
	{
		return st.holdForPortal && !s.portalOpen && s.secondsToPortal > 0 && s.secondsToPortal <= st.portalSoonSeconds
			&& s.essenceRoom() >= Math.min(st.portalMinRoom, 10);
	}

	static boolean portalReachable(Snapshot s)
	{
		if (s.portalTravelTicks < 0 || s.portalTicksLeft < 0)
		{
			return true;
		}
		return s.portalTravelTicks < s.portalTicksLeft;
	}

	private static String nextPortalHint(Snapshot s)
	{
		if (s.secondsSincePortal < 0)
		{
			return "";
		}
		return "Next portal in about " + Math.max(0, 140 - s.secondsSincePortal) + "s";
	}

	public static int ticksToSeconds(int ticks)
	{
		return (int) Math.round(ticks * 0.6);
	}

	/** For tests and the panel: which altars are currently usable. */
	public static boolean usable(Snapshot s, Altar a)
	{
		return AltarChooser.usable(s).contains(a);
	}
}

package com.toadfx.gotrcoach.plan;

/** Planner tuning, copied from the config each tick so the planner stays pure. */
public class PlannerSettings
{
	public Strategy strategy = Strategy.TEAM;
	public AltarMode altarMode = AltarMode.EVEN_POINTS;
	/** 0 means use the strategy default. */
	public int openingFragments;
	/** -1 means use the strategy default. */
	public int craftLeadSeconds = -1;
	/** On mass worlds, chisel only this much essence for the first altar trip (wiki: 30). */
	public int massFirstTripEssence = 30;
	/** Only go back to the workbench to top up if at least this much more essence fits. */
	public int topUpMin = 5;
	/** Smallest load worth an altar trip. */
	public int minEssenceForAltar = 10;
	/** Guardians you want up before you put cells into barriers instead. */
	public int guardiansWanted = 4;
	/** Energy difference before balance overrides the altar mode. */
	public int maxImbalance = 200;
	public boolean balanceWithBanked = true;
	/** Essence room needed to make the huge-remains portal worth taking. */
	public int portalMinRoom = 20;
	/** Portal first: drop everything else (stones, cells, crafting) when a portal is open and reachable. */
	public boolean portalAlways = true;
	/** Don't start an altar trip when a portal is due within portalSoonSeconds (you'd be stuck in the altar). */
	public boolean holdForPortal = true;
	public int portalSoonSeconds = 15;
	public boolean depositRunes = false;
	/** Deposit runes once free slots fall below this. */
	public int depositBelowFreeSlots = 24;
	public int unchargedCellsWanted = 10;
	/** Wiki grace-portal trick: hold the last stones until 95s after the last portal. */
	public boolean graceHold = true;

	public int openingFragments()
	{
		return openingFragments > 0 ? openingFragments : strategy.defaultOpeningFragments();
	}

	public int craftLeadSeconds()
	{
		return craftLeadSeconds >= 0 ? craftLeadSeconds : strategy.defaultCraftLeadSeconds();
	}
}

package com.toadfx.gotrcoach.plan;

import com.toadfx.gotrcoach.model.Altar;
import com.toadfx.gotrcoach.model.CellTier;
import com.toadfx.gotrcoach.state.GamePhase;
import com.toadfx.gotrcoach.state.Location;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;

/**
 * Everything the planner needs, as plain values. The plugin fills one of these every game tick;
 * tests build them by hand. No RuneLite types live here, so the planner can be unit tested.
 */
public class Snapshot
{
	public GamePhase phase = GamePhase.IDLE;
	public Location location = Location.OUTSIDE;
	/** The altar whose room the player is standing in, if any. */
	public Altar altarRoom;

	/** Seconds since the rift opened (0 before). */
	public int gameSeconds;
	/** Seconds until the rift opens, when known (-1 otherwise). */
	public int countdownSeconds = -1;
	/** During mining: seconds until the altars open. */
	public int secondsUntilAltars = -1;
	/** During crafting: ticks until the active altars rotate. */
	public int altarTicksLeft = -1;
	/** Great Guardian power, 0-100. */
	public int powerPercent;

	public Altar activeElemental;
	public Altar activeCatalytic;

	public boolean portalOpen;
	public int portalTicksLeft = -1;
	/** Seconds since the last huge-remains portal spawned (-1 if none this game). */
	public int secondsSincePortal = -1;
	/** Seconds until the next portal is expected (-1 when unknown or one is open). */
	public int secondsToPortal = -1;

	public int fragments;
	public int essence;
	public int essenceInPouches;
	public int pouchCapacity;
	public boolean hasPouches;
	public boolean pouchNeedsRepair;
	public int freeSlots = 28;
	public int elementalStones;
	public int catalyticStones;
	/** Stones that give 3 energy rather than 2. */
	public int polyStones;
	public CellTier chargedCell;
	public int unchargedCells;
	public boolean hasChisel = true;
	public boolean hasPickaxe = true;
	/** Inventory slots holding runes we crafted (stackable, so slots not runes). */
	public int runeSlots;

	public int energyElemental;
	public int energyCatalytic;
	public int bankedElemental = -1;
	public int bankedCatalytic = -1;
	public boolean yewLantern;

	/** Altar trips made this game. */
	public int altarTrips;
	/** True once the opening craft has started this game (so mining does not resume by mistake). */
	public boolean openingCraftStarted;

	public int guardians;
	public int guardiansMax = 10;

	public int runecraftLevel = 99;
	public int agilityLevel = 99;
	public Set<Altar> questLocked = EnumSet.noneOf(Altar.class);
	/** Portal talismans carried: each opens its guardian even when it isn't active. */
	public Set<Altar> talismans = EnumSet.noneOf(Altar.class);

	public boolean repairableTile;
	public boolean emptyTile;
	/** Lowest barrier health as a percent, -1 when unknown or no barriers. */
	public int lowestBarrierPercent = -1;

	/** Walking ticks from the player to each altar portal, when known. */
	public Map<Altar, Integer> altarTravelTicks = new EnumMap<>(Altar.class);
	/** Walking ticks to the huge remains portal, -1 when unknown. */
	public int portalTravelTicks = -1;

	public int stones()
	{
		return elementalStones + catalyticStones;
	}

	public int essenceCarried()
	{
		return essence + essenceInPouches;
	}

	/** Room left for essence across inventory and pouches. */
	public int essenceRoom()
	{
		return freeSlots + Math.max(0, pouchCapacity - essenceInPouches);
	}

	/** What's missing for the round: pickaxe, chisel, uncharged cells. Empty when ready. */
	public java.util.List<String> missingGear(int cellsWanted)
	{
		java.util.List<String> out = new java.util.ArrayList<>(3);
		if (!hasPickaxe)
		{
			out.add("pickaxe");
		}
		if (!hasChisel)
		{
			out.add("chisel");
		}
		if (unchargedCells < cellsWanted)
		{
			out.add((cellsWanted - unchargedCells) + " uncharged cells");
		}
		return out;
	}

	public boolean inGame()
	{
		return phase == GamePhase.MINING || phase == GamePhase.CRAFTING || phase == GamePhase.CLOSING;
	}

	public boolean canEnter(Altar altar)
	{
		return altar != null && runecraftLevel >= altar.getLevel() && !questLocked.contains(altar);
	}
}

